feedbackvariables.text:
/* On vérifie la présence exacte de la chaîne */
test_exact:is(ssearch("systeme:Satellite", ans1) # false);
/* On crée une liste des mots attendus pour la suite */
mots_attendus: [ "Lune","Terre"];

/* On vérifie si TOUS les mots sont présents dans la réponse */
tous_presents: all_listp(lambda([x], ssearch(x, ans1) # false), mots_attendus);


/* pour les flèches*/
/* On vérifie la présence exacte des chaînes */
test_fleche1 : is((ssearch("Terre-Satellite-dashed", ans1) # false) or (ssearch("Satellite-Terre-dashed", ans1) # false));
test_fleche1_wrong : is((ssearch("Terre-Satellite-solid", ans1) # false) or  (ssearch("Satellite-Terre-solid", ans1) # false));

test_fleche2 : is((ssearch("Lune-Satellite-dashed", ans1) # false) or (ssearch("Satellite-Lune-dashed", ans1) # false));
test_fleche2_wrong : is((ssearch("Lune-Satellite-solid", ans1) # false) or  (ssearch("Satellite-Lune-solid", ans1) # false));

/*    TESTS DES PLACEMENTS    */

/* On vérifie la présence exacte de la chaîne nip*/
test_vide:is(ssearch("nipvide", ans1) # false);
test_systèmedepilotage:is(ssearch("nipsystèmedepilotage", ans1) # false);
test_propulseurs:is(ssearch("nippropulseurs", ans1) # false);
test_air:is(ssearch("nipair", ans1) # false);
/*On verifie que tout les hors système sont présents */
tous_hors_sys_ok: test_vide and test_systèmedepilotage and test_propulseurs and test_air ;
